using Microsoft.Data.SqlClient;using System.Data;using He_Thong_GYM.Models;
namespace He_Thong_GYM.DAL;
public sealed class DangKyDAL
{
 public async Task<List<ThanhVien>> LayThanhVienAsync(){const string q="SELECT tv.MaTV,tv.HoTen,tv.NgaySinh,tv.GioiTinh,tv.SDT,tv.Email,tv.DiaChi,tv.NgayDangKy,tv.MaLoaiTV,lt.TenLoai,tv.TrangThai FROM dbo.ThanhVien tv JOIN dbo.LoaiThanhVien lt ON lt.MaLoaiTV=tv.MaLoaiTV WHERE tv.TrangThai=N'Hoạt động' ORDER BY tv.HoTen;";var k=new List<ThanhVien>();await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand(q,c);await c.OpenAsync();await using var r=await m.ExecuteReaderAsync();while(await r.ReadAsync())k.Add(new ThanhVien{MaTV=r.GetInt32(0),HoTen=r.GetString(1),NgaySinh=r.GetDateTime(2),GioiTinh=r.IsDBNull(3)?null:r.GetString(3),SDT=r.GetString(4),Email=r.IsDBNull(5)?null:r.GetString(5),DiaChi=r.IsDBNull(6)?null:r.GetString(6),NgayDangKy=r.GetDateTime(7),MaLoaiTV=r.GetInt32(8),TenLoai=r.GetString(9),TrangThai=r.GetString(10)});return k;}
 public async Task<List<GoiTap>> LayGoiTapAsync(){const string q="SELECT MaGoi,TenGoi,ThoiHanNgay,Gia,MoTa,TrangThai FROM dbo.GoiTap WHERE TrangThai=N'Đang áp dụng' ORDER BY TenGoi;";var k=new List<GoiTap>();await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand(q,c);await c.OpenAsync();await using var r=await m.ExecuteReaderAsync();while(await r.ReadAsync())k.Add(new GoiTap{MaGoi=r.GetInt32(0),TenGoi=r.GetString(1),ThoiHanNgay=r.GetInt32(2),Gia=r.GetDecimal(3),MoTa=r.IsDBNull(4)?null:r.GetString(4),TrangThai=r.GetString(5)});return k;}
 public async Task<List<KhuyenMai>> LayKhuyenMaiAsync(){const string q="SELECT MaKM,TenKM,PhanTramGiam FROM dbo.KhuyenMai WHERE TrangThai=N'Hoạt động' AND CAST(GETDATE() AS date) BETWEEN NgayBatDau AND NgayKetThuc ORDER BY TenKM;";var k=new List<KhuyenMai>{new(){MaKM=null,TenKM="Không áp dụng",PhanTramGiam=0}};await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand(q,c);await c.OpenAsync();await using var r=await m.ExecuteReaderAsync();while(await r.ReadAsync())k.Add(new KhuyenMai{MaKM=r.GetInt32(0),TenKM=r.GetString(1),PhanTramGiam=r.GetDecimal(2)});return k;}
 public async Task<List<HuanLuyenVien>> LayHLVAsync(){const string q="SELECT h.MaHLV,h.MaNV,n.HoTen,h.ChuyenMon,h.KinhNghiem,h.PhiThue,n.TrangThai FROM dbo.HuanLuyenVien h JOIN dbo.NhanVien n ON n.MaNV=h.MaNV WHERE n.TrangThai=N'Đang làm' ORDER BY n.HoTen;";var k=new List<HuanLuyenVien>();await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand(q,c);await c.OpenAsync();await using var r=await m.ExecuteReaderAsync();while(await r.ReadAsync())k.Add(new HuanLuyenVien{MaHLV=r.GetInt32(0),MaNV=r.GetInt32(1),HoTen=r.GetString(2),ChuyenMon=r.IsDBNull(3)?null:r.GetString(3),KinhNghiem=r.IsDBNull(4)?null:r.GetInt32(4),PhiThue=r.IsDBNull(5)?null:r.GetDecimal(5),TrangThaiNhanVien=r.GetString(6)});return k;}
 public async Task<List<LichSuDangKy>> LayLichSuGoiAsync(){const string q="SELECT d.MaDKG,t.HoTen,g.TenGoi,d.NgayBatDau,d.NgayKetThuc,d.GiaSauGiam,d.TrangThai FROM dbo.DangKyGoi d JOIN dbo.ThanhVien t ON t.MaTV=d.MaTV JOIN dbo.GoiTap g ON g.MaGoi=d.MaGoi ORDER BY d.MaDKG DESC;";return await LayLichSuAsync(q);}
 public async Task<List<LichSuDangKy>> LayLichSuPTAsync(){const string q="SELECT d.MaDKPT,t.HoTen,n.HoTen,d.NgayBatDau,d.NgayKetThuc,d.TongTien,d.TrangThai FROM dbo.DangKyPT d JOIN dbo.ThanhVien t ON t.MaTV=d.MaTV JOIN dbo.HuanLuyenVien h ON h.MaHLV=d.MaHLV JOIN dbo.NhanVien n ON n.MaNV=h.MaNV ORDER BY d.MaDKPT DESC;";return await LayLichSuAsync(q);}
 private static async Task<List<LichSuDangKy>> LayLichSuAsync(string q){var k=new List<LichSuDangKy>();await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand(q,c);await c.OpenAsync();await using var r=await m.ExecuteReaderAsync();while(await r.ReadAsync())k.Add(new LichSuDangKy{MaDangKy=r.GetInt32(0),ThanhVien=r.GetString(1),DichVu=r.GetString(2),NgayBatDau=r.GetDateTime(3),NgayKetThuc=r.GetDateTime(4),TongTien=r.GetDecimal(5),TrangThai=r.GetString(6)});return k;}
 public async Task<(int MaDangKy,int MaHD)> DangKyGoiAsync(int tv,int goi,int? km,DateTime ngay,int nv){await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand("dbo.sp_DangKyGoiTap",c){CommandType=CommandType.StoredProcedure};m.Parameters.AddWithValue("@MaTV",tv);m.Parameters.AddWithValue("@MaGoi",goi);m.Parameters.AddWithValue("@MaKM",(object?)km??DBNull.Value);m.Parameters.AddWithValue("@NgayBatDau",ngay.Date);m.Parameters.AddWithValue("@MaNV",nv);var dk=m.Parameters.Add("@MaDKG",SqlDbType.Int);dk.Direction=ParameterDirection.Output;var hd=m.Parameters.Add("@MaHD",SqlDbType.Int);hd.Direction=ParameterDirection.Output;await c.OpenAsync();await m.ExecuteNonQueryAsync();return((int)dk.Value,(int)hd.Value);}
 public async Task<(int MaDangKy,int MaHD)> DangKyPTAsync(int tv,int hlv,int buoi,int? km,DateTime ngay,DateTime ketThuc,int nv){await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand("dbo.sp_DangKyPT",c){CommandType=CommandType.StoredProcedure};m.Parameters.AddWithValue("@MaTV",tv);m.Parameters.AddWithValue("@MaHLV",hlv);m.Parameters.AddWithValue("@SoBuoi",buoi);m.Parameters.AddWithValue("@MaKM",(object?)km??DBNull.Value);m.Parameters.AddWithValue("@NgayBatDau",ngay.Date);m.Parameters.AddWithValue("@NgayKetThuc",ketThuc.Date);m.Parameters.AddWithValue("@MaNV",nv);var dk=m.Parameters.Add("@MaDKPT",SqlDbType.Int);dk.Direction=ParameterDirection.Output;var hd=m.Parameters.Add("@MaHD",SqlDbType.Int);hd.Direction=ParameterDirection.Output;await c.OpenAsync();await m.ExecuteNonQueryAsync();return((int)dk.Value,(int)hd.Value);}
}
